// DECIDE AUDIENCE / Plan Facts (generated by Tools/n8n/build-decide-audience.py — edit there, never the JSON).
// What the chat needs before the rule can decide it. The input is the template's item, trimmed to the nine fields:
// channel, profileId, chatId (the incoming message's `from`), chatLid (WhatsApp: the incoming webhook's whatsapp_chat_id —
// the code the chat's messages may be listed under; '' on Telegram), messageId, chatType, isBot, connectedAtMs and
// connectionPhone (Read Reply Mode's connection row: null when it had none — then Ensure Connection ran first, and its row
// gives the moment and the number). Stops, with no Wappi call and nothing written (Can Decide? sends them to Shape):
//   personal_unknown   a malformed input (an unknown channel, a sentinel profile, no chat or message id) or no moment;
//   personal_settling  the channel was connected less than SETTLE_MINUTES ago: what Wappi can read of the account may still
//                      be incomplete, and a decision taken on it would stand for good.
// A chat that is not a person by its input alone goes to Decide without a call — RULE_JS on the input facts: a WhatsApp
// group / channel / status suffix, the Telegram service account, a Telegram chat type that is not a person (a bot's reply
// arrives as chat_type bot), the webhook's is_bot, WhatsApp's chat with oneself (the digits of the chat id are the
// connected number's). Otherwise:
//   Telegram  the chat card gives the flags, the contact and the chat type (Read Card);
//   WhatsApp  the chat card, filtered by the digits of the chat id, gives the contact (Read Card) — except for a chat known
//             only by its code (an id ending in @lid): the filter does not search codes, so its contact is false and its
//             history decides.
// The history is asked only when it decides whether the chat is a client: RULE_JS with history false says business.
// AUDIENCE RULE - is this chat PERSONAL (the assistant stays out) or BUSINESS (a client)? ONE function, two runners:
// the Decide Audience Code node embeds this text verbatim (Tools/n8n/audience.py) and the app's ChatAudienceRule.Decide is its
// C# twin; both run every row of Tools/n8n/fixtures/audience-cases.json. Pure: no clock, no network, no n8n globals.
//
// f = { channel,   'whatsapp' | 'telegram'
//       chatId,    string
//       chatType,  string; Telegram: 'user' = a person, 'channel' | 'chat' | 'bot' = not a person, anything else ('' = not
//                  given included) = not recognised; WhatsApp: not used
//       flags,     { bot, support, self } | null; Telegram: null = the chat card was not received, WhatsApp: null = all false
//       contact,   true | false | null; a saved contact, null = not known
//       history,   true | false | null; a conversation before the connection, null = not known
//       owner }    null | 'personal' | 'business'; the owner's own decision, if there is one
// returns { kind: 'personal' | 'business', reason: 'nonhuman' | 'owner' | 'contact' | 'history' | 'new' | 'unknown' }
// A fact that is not given is not known: only a known "no" on both contact and history makes a new person.
function decideAudience(f) {
  const WA_NONHUMAN_SUFFIXES = ["@g.us", "@newsletter", "@broadcast"];
  const TG_SERVICE_IDS = ["777000"];
  const TG_NONHUMAN_TYPES = ["channel", "chat", "bot"];
  const TG_PERSON_TYPE = "user";
  const personal = (reason) => ({ kind: 'personal', reason: reason });
  const telegram = f.channel === 'telegram';
  // A channel that is neither is not decided: step 1 would not know which of its two halves applies.
  if (!telegram && f.channel !== 'whatsapp') return personal('unknown');
  const id = f.chatId == null ? '' : String(f.chatId);
  const type = typeof f.chatType === 'string' ? f.chatType : '';
  const flags = (f.flags && typeof f.flags === 'object') ? f.flags : null;
  const flag = (name) => !!(flags && flags[name]);

  // 1. Not a person: never a client, whatever the owner says.
  const nonhuman = telegram
    ? TG_SERVICE_IDS.indexOf(id) >= 0 || TG_NONHUMAN_TYPES.indexOf(type) >= 0 || flag('bot') || flag('support') || flag('self')
    : WA_NONHUMAN_SUFFIXES.some((suffix) => id.endsWith(suffix)) || flag('bot') || flag('self');
  if (nonhuman) return personal('nonhuman');
  // 2. Telegram without the chat card: a bot cannot be ruled out.
  if (telegram && flags === null) return personal('unknown');
  // 2a. Telegram with a chat type we do not recognise ('' included, any other spelling or case): it cannot be classified.
  if (telegram && type !== TG_PERSON_TYPE) return personal('unknown');
  // 3. The owner's own decision.
  if (f.owner === 'personal' || f.owner === 'business') return { kind: f.owner, reason: 'owner' };
  // 4-5. A saved contact, or a conversation that existed before the connection.
  if (f.contact) return personal('contact');
  if (f.history) return personal('history');
  // 6. Contact or history not known.
  if (f.contact !== false || f.history !== false) return personal('unknown');
  // 7. A new person.
  return { kind: 'business', reason: 'new' };
}
